//-------------------------------------------ANIMATION DE LA BARRE D'ENREGISTREMENT-----------------------------
void demarrer_animation_barre() {


    lv_obj_add_state(ui_btSaveData, LV_STATE_DISABLED);
    lv_obj_set_style_opa(ui_btSaveData, 110, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_add_state(ui_btHomeScr2, LV_STATE_DISABLED);
    lv_obj_add_state(ui_btSaveScr2, LV_STATE_DISABLED);

    // 1. On remet d'abord la barre à zéro
    lv_bar_set_value(ui_btRecordData, 0, LV_ANIM_OFF);

    // 2. Initialisation de l'animation
    lv_anim_init(&anim_bar);
    lv_anim_set_var(&anim_bar, ui_btRecordData); // L'objet à animer (ta barre)
    
    // 3. Définition des valeurs (de 0 à BUFFER_SIZE)
    lv_anim_set_values(&anim_bar, 0, BUFFER_SIZE); 
    
    // 4. Définition du temps (10 secondes = 10000 millisecondes)
    lv_anim_set_time(&anim_bar, DUREE_SEC*1000); 
    
    // 5. On indique à LVGL quelle fonction native utiliser pour modifier la valeur de la barre
    lv_anim_set_exec_cb(&anim_bar, (lv_anim_exec_xcb_t)lv_bar_set_value);
    
    // 6. On lance l'animation
    lv_anim_start(&anim_bar);
}

void stopper_animation_barre() {
    // Arrête l'animation en cours sur la barre
    lv_anim_del(ui_btRecordData, (lv_anim_exec_xcb_t)lv_bar_set_value);
    lv_bar_set_value(ui_btRecordData, 0, LV_ANIM_OFF);
    lv_obj_clear_state(ui_btSaveData, LV_STATE_DISABLED);
    lv_obj_set_style_opa(ui_btSaveData, 255, LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_obj_clear_state(ui_btHomeScr2, LV_STATE_DISABLED);
    lv_obj_clear_state(ui_btSaveScr2, LV_STATE_DISABLED);
}


